/* =========================================
   CONSTANTS & STATE
========================================= */
const HERO_TEXTS = [
  "Building Fast Websites!",
  "Crafting Modern UIs!",
  "Responsive Web Experiences!",
];

const TYPE_SPEED = 120;
const DELETE_SPEED = 60;
const PAUSE_TIME = 1800;
const OBSERVER_MARGIN = "-45% 0px -45% 0px";

let textIndex = 0;
let charIndex = 0;
let isDeleting = false;
let typingTimeout = null;
let activeLinkObserver = null;

/* =========================================
   THEME TOGGLE (DARK / LIGHT MODE)
========================================= */
function applySavedTheme() {
  if (localStorage.getItem("lightMode") === "true") {
    document.body.classList.add("light-mode");
  }
}

function initializeTheme() {
  const toggle = document.getElementById("theme");
  if (!toggle) return;

  toggle.checked = document.body.classList.contains("light-mode");

  toggle.addEventListener("change", () => {
    document.body.classList.toggle("light-mode");
    localStorage.setItem(
      "lightMode",
      document.body.classList.contains("light-mode")
    );
  });
}

/* =========================================
   MOBILE NAVIGATION MENU
========================================= */
function initializeMobileMenu() {
  const hamburger = document.getElementById("toggle_button");
  const navMenu = document.getElementById("nav-menu");
  if (!hamburger || !navMenu) return;

  const navLinks = navMenu.querySelectorAll("a");

  const closeMenu = () => {
    navMenu.classList.remove("nav-active");
    hamburger.classList.remove("fa-xmark");
    hamburger.classList.add("fa-bars");
    hamburger.setAttribute("aria-expanded", "false");
  };

  const toggleMenu = () => {
    const isOpen = navMenu.classList.toggle("nav-active");
    hamburger.classList.toggle("fa-bars", !isOpen);
    hamburger.classList.toggle("fa-xmark", isOpen);
    hamburger.setAttribute("aria-expanded", String(isOpen));
  };

  hamburger.addEventListener("click", toggleMenu);

  hamburger.addEventListener("keydown", (e) => {
    if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      toggleMenu();
    }
  });

  navLinks.forEach((link) => link.addEventListener("click", closeMenu));

  document.addEventListener("click", (e) => {
    if (
      navMenu.classList.contains("nav-active") &&
      !navMenu.contains(e.target) &&
      !hamburger.contains(e.target)
    ) {
      closeMenu();
    }
  });

  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && navMenu.classList.contains("nav-active")) {
      closeMenu();
    }
  });
}

/* =========================================
   NAVIGATION ACTIVE LINK SPY
========================================= */
function initializeActiveLinks() {
  const sections = document.querySelectorAll("section[id]");
  const navLinks = document.querySelectorAll(".nav-link");
  if (!sections.length || !navLinks.length) return;

  activeLinkObserver = new IntersectionObserver(
    (entries) => {
      entries.forEach((entry) => {
        if (!entry.isIntersecting) return;

        const targetHref = `#${entry.target.id}`;
        navLinks.forEach((link) => {
          const isMatch = link.getAttribute("href") === targetHref;
          link.classList.toggle("active-link", isMatch);

          if (isMatch) {
            link.setAttribute("aria-current", "page");
          } else {
            link.removeAttribute("aria-current");
          }
        });
      });
    },
    { rootMargin: OBSERVER_MARGIN, threshold: 0 }
  );

  sections.forEach((section) => activeLinkObserver.observe(section));
}

/* =========================================
   HERO TYPING EFFECT
========================================= */
function startTyping(delay) {
  clearTimeout(typingTimeout);
  typingTimeout = setTimeout(typeEffect, delay);
}

function typeEffect() {
  const textElement = document.querySelector(".textEffect");
  if (!textElement || !document.body.contains(textElement)) {
    clearTimeout(typingTimeout);
    return;
  }

  const currentText = HERO_TEXTS[textIndex];
  charIndex += isDeleting ? -1 : 1;
  textElement.textContent = currentText.slice(0, charIndex);

  if (!isDeleting && charIndex === currentText.length) {
    isDeleting = true;
    startTyping(PAUSE_TIME);
    return;
  }

  if (isDeleting && charIndex === 0) {
    isDeleting = false;
    textIndex = (textIndex + 1) % HERO_TEXTS.length;
  }

  startTyping(isDeleting ? DELETE_SPEED : TYPE_SPEED);
}

/* =========================================
   PROJECT CARD TABS
========================================= */
function initializeProjectTabs() {
  document.addEventListener("click", (e) => {
    const tabBtn = e.target.closest(".tab-btn");
    if (!tabBtn) return;

    e.preventDefault();
    const card = tabBtn.closest(".project-card");
    if (!card) return;

    const target = tabBtn.getAttribute("data-tab");

    card.querySelectorAll(".tab-btn").forEach((btn) => {
      btn.classList.remove("active");
      btn.setAttribute("aria-selected", "false");
    });

    card.querySelectorAll(".tab-pane").forEach((pane) => {
      pane.classList.remove("active");
    });

    tabBtn.classList.add("active");
    tabBtn.setAttribute("aria-selected", "true");

    const activePane = card.querySelector(`.tab-pane[data-pane="${target}"]`);
    if (activePane) {
      activePane.classList.add("active");
    }
  });
}

/* =========================================
   PROJECTS MOBILE SLIDER (BUTTONS + DOTS)
========================================= */
function initializeProjectSlider() {
  const slider = document.getElementById("projectSlider");
  const prevBtn = document.getElementById("slideLeft");
  const nextBtn = document.getElementById("slideRight");
  const dots = document.querySelectorAll(".slider-dot");

  if (!slider || !prevBtn || !nextBtn || !dots.length) return;

  const cards = slider.querySelectorAll(".project-card");
  if (!cards.length) return;

  let currentIndex = 0;

  const updateDots = (index) => {
    dots.forEach((dot, i) => {
      dot.classList.toggle("active", i === index);
    });
  };

  const goToSlide = (index) => {
    currentIndex = (index + cards.length) % cards.length;
    const baseOffset = cards[0].offsetLeft;
    const targetLeft = cards[currentIndex].offsetLeft - baseOffset;

    slider.scrollTo({
      left: targetLeft,
      behavior: "smooth",
    });

    updateDots(currentIndex);
  };

  nextBtn.addEventListener("click", () => goToSlide(currentIndex + 1));
  prevBtn.addEventListener("click", () => goToSlide(currentIndex - 1));

  dots.forEach((dot, index) => {
    dot.addEventListener("click", () => goToSlide(index));
  });

  // Sync dots when user swipes manually on phone
  let scrollTimer;
  slider.addEventListener(
    "scroll",
    () => {
      clearTimeout(scrollTimer);
      scrollTimer = setTimeout(() => {
        const step =
          cards.length > 1
            ? cards[1].offsetLeft - cards[0].offsetLeft
            : slider.clientWidth;

        if (!step) return;

        const newIndex = Math.round(slider.scrollLeft / step);
        if (newIndex >= 0 && newIndex < cards.length) {
          currentIndex = newIndex;
          updateDots(currentIndex);
        }
      }, 60);
    },
    { passive: true }
  );
}

/* =========================================
   FOOTER YEAR & PRELOADER
========================================= */
function initializeFooterYear() {
  const yearEl = document.getElementById("current-year");
  if (yearEl) {
    yearEl.textContent = new Date().getFullYear();
  }
}

function hideLoader() {
  const loader = document.getElementById("loader");
  if (loader && !loader.classList.contains("hide")) {
    loader.classList.add("hide");
  }
}

/* =========================================
   INITIALIZATION & LIFECYCLE
========================================= */
applySavedTheme();

document.addEventListener("DOMContentLoaded", () => {
  if (typeof AOS !== "undefined") {
    AOS.init({
      once: false,
      duration: 500,
    });
  }

  initializeTheme();
  initializeMobileMenu();
  initializeActiveLinks();
  initializeProjectTabs();
  initializeProjectSlider();
  initializeProjectSlider();
  initializeFooterYear();
  startTyping(TYPE_SPEED);
});

window.addEventListener("load", () => {
  setTimeout(hideLoader, 500);

  if (typeof AOS !== "undefined") {
    setTimeout(() => AOS.refresh(), 600);
  }
});

// Safety fallback so loader never gets stuck on slow connections
setTimeout(hideLoader, 3000);

window.addEventListener("beforeunload", () => {
  clearTimeout(typingTimeout);
  if (activeLinkObserver) {
    activeLinkObserver.disconnect();
  }
});
